class MyCalendarTwo {
    private java.util.List<int[]> bookings;
    private java.util.List<int[]> overlaps;

    public MyCalendarTwo() {
        bookings = new java.util.ArrayList<>();
        overlaps = new java.util.ArrayList<>();
    }

    public boolean book(int start, int end) {
        for (int[] ov : overlaps) {
            if (start < ov[1] && end > ov[0]) return false;
        }
        for (int[] b : bookings) {
            int os = Math.max(start, b[0]);
            int oe = Math.min(end, b[1]);
            if (os < oe) overlaps.add(new int[]{os, oe});
        }
        bookings.add(new int[]{start, end});
        return true;
    }
}

import java.util.*;

class MyCalendarTwo {
    private TreeMap<Integer, Integer> timeline;

    public MyCalendarTwo() {
        timeline = new TreeMap();
    }

    public boolean book(int start, int end) {
        timeline.put(start, timeline.getOrDefault(start, 0) + 1);
        timeline.put(end, timeline.getOrDefault(end, 0) - 1);
        int count = 0;
        for (Map.Entry<Integer, Integer> entry : timeline.entrySet()) {
            count += entry.getValue().intValue();
            if (count >= 3) {
                timeline.put(start, timeline.get(start).intValue() - 1);
                if (timeline.get(start).intValue() == 0) timeline.remove(start);
                timeline.put(end, timeline.get(end).intValue() + 1);
                if (timeline.get(end).intValue() == 0) timeline.remove(end);
                return false;
            }
        }
        return true;
    }
}
